// src/store/canonical.ts
function canonical(value) {
  if (value === null)
    return "null";
  switch (typeof value) {
    case "boolean":
      return value ? "true" : "false";
    case "number":
      if (!Number.isFinite(value))
        throw new Error(`not a JSON number: ${value}`);
      return JSON.stringify(value);
    case "string":
      if (!value.isWellFormed())
        throw new Error("a string with a lone surrogate");
      return JSON.stringify(value);
    case "object": {
      if (Array.isArray(value)) {
        if (Array.from(value.keys()).some((i) => !(i in value)))
          throw new Error("an array with a hole");
        return `[${value.map(canonical).join(",")}]`;
      }
      const proto = Object.getPrototypeOf(value);
      if (proto !== Object.prototype && proto !== null)
        throw new Error("not a plain object");
      const keys = Object.keys(value).sort();
      const record = value;
      return `{${keys.filter((key) => record[key] !== undefined).map((key) => `${canonical(key)}:${canonical(record[key])}`).join(",")}}`;
    }
    default:
      throw new Error(`not JSON: ${typeof value}`);
  }
}

// src/store/id.ts
var alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ";
function newId(time = Date.now(), random = crypto.getRandomValues(new Uint8Array(16))) {
  let stamp = "";
  for (let rest = time, i = 0;i < 10; i++, rest = Math.floor(rest / 32))
    stamp = alphabet[rest % 32] + stamp;
  let tail = "";
  for (let i = 0;i < 16; i++)
    tail += alphabet[random[i] % 32];
  return stamp + tail;
}

// field/components/jsx.ts
function h(tag, props, ...children) {
  if (typeof tag === "function")
    return tag({ ...props, children });
  const made = document.createElement(tag);
  for (const [key, value] of Object.entries(props ?? {}))
    set(made, key, value);
  made.append(...nodesOf(children));
  return made;
}
var events = { doubleclick: "dblclick" };
function set(made, key, value) {
  if (value === undefined || value === null)
    return;
  if (key.startsWith("on")) {
    const event = key.slice(2).toLowerCase();
    if (typeof value === "function")
      made.addEventListener(events[event] ?? event, value);
    return;
  }
  if (key === "html")
    made.innerHTML = String(value);
  else if (key === "style" && typeof value === "object")
    Object.assign(made.style, value);
  else if (value === false) {
    if (key.startsWith("aria-"))
      made.setAttribute(key, "false");
  } else
    made.setAttribute(key === "className" ? "class" : key, value === true ? "" : String(value));
}
function nodesOf(children) {
  return children.flatMap((child) => {
    if (Array.isArray(child))
      return nodesOf(child);
    if (child === null || child === undefined || typeof child === "boolean")
      return [];
    return [typeof child === "number" ? String(child) : child];
  });
}

// field/components/menu.ts
var standing;
function overlay(x, y, content, from) {
  standing?.();
  const returnTo = document.activeElement ?? from;
  const menu = document.createElement("div");
  menu.className = "menu";
  menu.setAttribute("role", "dialog");
  menu.append(content);
  const keys = (event) => {
    if (event.key === "Escape")
      return event.preventDefault(), close();
  };
  const outside = (event) => !menu.contains(event.target) && close();
  const lay = () => {
    const { width, height } = menu.getBoundingClientRect();
    menu.style.left = `${Math.max(8, Math.min(x, innerWidth - width - 8))}px`;
    menu.style.top = `${Math.max(8, Math.min(y, innerHeight - height - 8))}px`;
  };
  const growing = new ResizeObserver(lay);
  function close() {
    growing.disconnect();
    removeEventListener("pointerdown", outside, true);
    removeEventListener("keydown", keys, true);
    if (standing === close)
      standing = undefined;
    if (!menu.isConnected)
      return;
    menu.remove();
    returnTo.focus?.();
  }
  addEventListener("pointerdown", outside, true);
  addEventListener("keydown", keys, true);
  standing = close;
  from.append(menu);
  lay();
  growing.observe(menu);
  return close;
}

